$file = "X:\code\copilot-worktrees\P04\cirvine-msft-potential-pancake\assets\config.txt"
$content = [System.IO.File]::ReadAllText($file)

# Allowed characters: space, A-Z, 0-9, +|/\_*\.#():=-
$allowedChars = @(' ', [char[]]'ABCDEFGHIJKLMNOPQRSTUVWXYZ', [char[]]'0123456789', '+', '|', '/', '\', '_', '*', '.', '#', '(', ')', ':', '=', '-')
$allowedSet = @{}
$allowedChars | ForEach-Object { $allowedSet[$_] = $true }

# Check for disallowed characters
$disallowed = @()
$i = 0
foreach ($char in $content.ToCharArray()) {
    if ($char -ne "`n" -and $char -ne "`r" -and -not $allowedSet[$char]) {
        $disallowed += "Position $i: '$char' (code $(ord([char]$char)))"
    }
    $i++
}

if ($disallowed.Count -gt 0) {
    Write-Host "DISALLOWED CHARACTERS FOUND:"
    $disallowed | ForEach-Object { Write-Host "  $_" }
} else {
    Write-Host "✓ Only allowed characters used"
}

Write-Host ""

# Check for CONFIG
if ($content -like "*CONFIG*") {
    $count = ([regex]::Matches($content, "CONFIG")).Count
    Write-Host "✓ Contains 'CONFIG' substring ($count occurrences)"
} else {
    Write-Host "✗ Does not contain 'CONFIG'"
}

