$file = "X:\code\copilot-worktrees\P04\cirvine-msft-potential-pancake\assets\config.txt"
$content = [System.IO.File]::ReadAllText($file)
$lines = [System.IO.File]::ReadAllLines($file)
$bytes = [System.IO.File]::ReadAllBytes($file)

Write-Host "=== VERIFICATION REPORT ===" -ForegroundColor Cyan
Write-Host ""

# 1. Line count
Write-Host "1. EXACT LINE COUNT (should be 12):"
Write-Host "   Lines: $($lines.Count) ✓" -ForegroundColor Green
Write-Host ""

# 2. Line lengths
Write-Host "2. LINE LENGTHS (should be 20-48 chars):"
$lengthsOK = $true
for ($i = 0; $i -lt $lines.Count; $i++) {
    $len = $lines[$i].Length
    $ok = ($len -ge 20 -and $len -le 48)
    $status = if ($ok) { "✓" } else { "✗" }
    Write-Host "   Line $($i+1): $len chars $status"
    if (-not $ok) { $lengthsOK = $false }
}
Write-Host "   All within range: $(if ($lengthsOK) { 'YES ✓' } else { 'NO ✗' })" -ForegroundColor $(if ($lengthsOK) { 'Green' } else { 'Red' })
Write-Host ""

# 3. Allowed characters
Write-Host "3. CHARACTER SET (ASCII only, uppercase letters only):"
$allowedSet = @{}
' ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+|/\_*\.#():=-'.ToCharArray() | ForEach-Object { $allowedSet[$_] = $true }

$disallowed = @()
foreach ($char in $content.ToCharArray()) {
    if ($char -ne "`n" -and $char -ne "`r" -and -not $allowedSet[$char]) {
        $disallowed += $char
    }
}

if ($disallowed.Count -eq 0) {
    Write-Host "   Only allowed characters: YES ✓" -ForegroundColor Green
} else {
    Write-Host "   Only allowed characters: NO ✗" -ForegroundColor Red
    Write-Host "   Disallowed chars: $($disallowed -join ', ')"
}
Write-Host ""

# 4. CONFIG substring
Write-Host "4. CONTAINS 'CONFIG' SUBSTRING:"
if ($content -like "*CONFIG*") {
    $count = ([regex]::Matches($content, "CONFIG")).Count
    Write-Host "   Found: YES ✓ ($count occurrences)" -ForegroundColor Green
} else {
    Write-Host "   Found: NO ✗" -ForegroundColor Red
}
Write-Host ""

# 5. No trailing whitespace
Write-Host "5. NO TRAILING WHITESPACE:"
$trailingWS = $false
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '\s+$') {
        Write-Host "   Line $($i+1): Has trailing whitespace ✗" -ForegroundColor Red
        $trailingWS = $true
    }
}
if (-not $trailingWS) {
    Write-Host "   All lines clean: YES ✓" -ForegroundColor Green
}
Write-Host ""

# 6. Single trailing newline
Write-Host "6. FILE ENDS WITH SINGLE NEWLINE:"
$lastByte = $bytes[-1]
$secondLastByte = if ($bytes.Count -gt 1) { $bytes[-2] } else { $null }
if ($lastByte -eq 10 -and $secondLastByte -ne 10) {
    Write-Host "   Proper termination: YES ✓" -ForegroundColor Green
} else {
    Write-Host "   Proper termination: NO ✗" -ForegroundColor Red
}
Write-Host ""

# 7. Show the content
Write-Host "=== FILE CONTENT ===" -ForegroundColor Cyan
for ($i = 0; $i -lt $lines.Count; $i++) {
    Write-Host "Line $($i+1) [$($lines[$i].Length.ToString().PadLeft(2)) chars]: $($lines[$i])"
}
Write-Host ""

Write-Host "=== FILE PATH ===" -ForegroundColor Cyan
Write-Host $file

